/**
 * Route Collection and Discovery for Build
 */
import { serverLogger as logger } from "../utils/index.js";
import { isNotFoundError } from "../platform/compat/fs.js";
import { join, relative } from "../platform/compat/path/index.js";
import { discoverFiles } from "../utils/file-discovery.js";
import { isDynamicRoute, isDynamicSegment } from "../utils/route-path-utils.js";
import { compareStrings } from "../utils/compare.js";
const PAGE_EXTENSIONS = [".mdx", ".md", ".tsx", ".jsx", ".ts", ".js"];
const PAGE_CANDIDATES = ["page.mdx", "page.md", "page.tsx", "page.jsx", "page.ts", "page.js"];
const PAGES_LAYOUT_CANDIDATES = new Set(PAGE_EXTENSIONS.map((extension) => `layout${extension}`));
function convertToSlug(relativePath) {
    return (relativePath
        .replace(/\\/g, "/")
        .replace(/\.(mdx|md|tsx|jsx|ts|js)$/, "")
        .replace(/\/index$/, "") || "index");
}
function isPagesApiDirectoryDescendant(relativePath) {
    return relativePath.replace(/\\/g, "/").startsWith("api/");
}
function isPagesLayoutFile(relativePath) {
    const fileName = relativePath.replace(/\\/g, "/").split("/").pop();
    return fileName !== undefined && PAGES_LAYOUT_CANDIDATES.has(fileName.toLowerCase());
}
function shouldIncludeRoute(path, include, exclude) {
    if (include?.length && !include.some((p) => path.startsWith(p)))
        return false;
    if (exclude?.length && exclude.some((p) => path.startsWith(p)))
        return false;
    return true;
}
// Route discovery walks the project with `readDir`, which yields entries in
// filesystem order -- insertion order on some filesystems, hash order on
// others. Leaving that order in place makes the build's route list, and every
// artifact derived from it (`ssgPaths`, the build manifest, build logs),
// depend on how the checkout happened to land on disk.
//
// The route path alone is not a total order: two sources can collapse onto one
// route (`pages/about.tsx` and `pages/about/index.tsx` both become `/about`,
// and a nested `app/app/page.tsx` re-roots onto `/`). Ties there would keep
// their filesystem order, and consumers keyed on the route path -- code
// splitting derives one entry name per route -- would still bundle a different
// source per checkout. The source file breaks the tie, so the full ordering is
// reproducible across machines and runs.
function byPagesRoute(a, b) {
    return compareStrings(a.path, b.path) || compareStrings(a.file, b.file);
}
function byAppRoute(a, b) {
    return compareStrings(a.path, b.path) || compareStrings(a.pageFile, b.pageFile);
}
export async function collectPagesRoutes(adapter, projectDir, include, exclude, pagesDirectory = "pages") {
    const routes = [];
    const pagesDir = join(projectDir, pagesDirectory);
    try {
        await adapter.fs.stat(pagesDir);
    }
    catch (error) {
        if (isNotFoundError(error))
            return routes;
        throw error;
    }
    for await (const file of discoverFiles({ baseDir: pagesDir, extensions: PAGE_EXTENSIONS, adapter })) {
        const relativePath = relative(pagesDir, file.path);
        if (isPagesApiDirectoryDescendant(relativePath) || isPagesLayoutFile(relativePath))
            continue;
        const slug = convertToSlug(relativePath);
        const pathForRoute = `/${slug === "index" ? "" : slug}`;
        if (isDynamicRoute(pathForRoute))
            continue;
        if (!shouldIncludeRoute(pathForRoute, include, exclude))
            continue;
        routes.push({ path: pathForRoute, file: file.path, slug });
    }
    return routes.sort(byPagesRoute);
}
/**
 * Collect App Router literal routes (static analyzable)
 */
export async function collectAppRoutes(adapter, projectDir, include, exclude, appDirectory = "app") {
    const collected = [];
    const appRoot = join(projectDir, appDirectory);
    try {
        await adapter.fs.stat(appRoot);
    }
    catch (error) {
        if (isNotFoundError(error))
            return collected;
        throw error;
    }
    await walkAppSSG(adapter, appRoot, [], [appRoot], collected);
    logger.debug(`Found ${collected.length} App Router static routes`);
    return collected
        .filter((r) => shouldIncludeRoute(r.path, include, exclude))
        .sort(byAppRoute);
}
function isForceDynamic(source) {
    // Regex-based heuristic: matches the common `export const dynamic = "force-dynamic"`
    // declaration. Known limitations: will miss `"force-dynamic" as const`, template literals,
    // and re-exports; will false-positive on commented-out lines. AST parsing would be more
    // accurate but is too heavy for this build-time path.
    return /export\s+const\s+dynamic\s*=\s*["']force-dynamic["']/.test(source);
}
async function walkAppSSG(adapter, dir, segs, segDirs, collected) {
    const baseName = dir.split("/").pop() ?? "";
    if (isDynamicSegment(baseName))
        return;
    for (const filePath of PAGE_CANDIDATES.map((n) => join(dir, n))) {
        let isFile = false;
        try {
            isFile = (await adapter.fs.stat(filePath)).isFile;
        }
        catch (error) {
            if (isNotFoundError(error))
                continue;
            throw error;
        }
        if (!isFile)
            continue;
        const src = await adapter.fs.readFile(filePath);
        if (isForceDynamic(src))
            break;
        const path = `/${segs.join("/")}`;
        collected.push({
            path: path === "/" ? "/" : path,
            pageFile: filePath,
            segments: [...segs],
            segmentDirs: [...segDirs],
        });
        break;
    }
    for await (const entry of adapter.fs.readDir(dir)) {
        if (!entry.isDirectory)
            continue;
        const nextDir = join(dir, entry.name);
        await walkAppSSG(adapter, nextDir, entry.name === "app" ? [] : [...segs, entry.name], [...segDirs, nextDir], collected);
    }
}
